import { S3Client } from '@aws-sdk/client-s3';
import { env } from '../config/env';

/**
 * S3Client configured for Neon Object Storage.
 *
 * Best practice per Neon docs:
 * - forcePathStyle: true is required for Neon Object Storage.
 * - Endpoint, region, and credentials map to the AWS_* variables generated by `neon deploy`.
 */
export const storageClient = new S3Client({
  forcePathStyle: true,
  ...(env.AWS_ENDPOINT_URL_S3 ? { endpoint: env.AWS_ENDPOINT_URL_S3 } : {}),
  ...(env.AWS_REGION ? { region: env.AWS_REGION } : {}),
  ...(env.AWS_ACCESS_KEY_ID && env.AWS_SECRET_ACCESS_KEY
    ? {
        credentials: {
          accessKeyId: env.AWS_ACCESS_KEY_ID,
          secretAccessKey: env.AWS_SECRET_ACCESS_KEY,
        },
      }
    : {}),
});

export const STORAGE_BUCKET = 'assets';
